insert into fcps_mcq_stage (id, subject_name, chapter_name, question, options, correct_answer, explanation) values
('127caedc-4b86-5bf1-88e9-a2ef1747f504'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Total body water as percentage of body weight in an average adult male is approximately:', '["90%","70%","50%","60%","80%"]'::jsonb, '60%', 'TBW constitutes about 60% of body weight in adult males.'),
('89f94283-7381-532b-82f6-35d6884d3dc3'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Total body water as percentage of body weight in an average adult female is approximately:', '["50%","60%","40%","55%","45%"]'::jsonb, '50%', 'Females have lower TBW (~50%) due to higher body fat content.'),
('da66aa43-e225-579e-8e79-ee2d7020b04f'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The largest fluid compartment in the body is:', '["Plasma","Interstitial fluid","Intracellular fluid","Lymph","Transcellular fluid"]'::jsonb, 'Intracellular fluid', 'ICF accounts for about 40% of body weight, making it the largest compartment.'),
('16f4b3cb-579d-5a3c-a190-57076852d903'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Extracellular fluid volume is approximately what percentage of body weight?', '["50%","20%","40%","10%","30%"]'::jsonb, '20%', 'ECF constitutes about 20% of body weight (plasma 5% + interstitial 15%).'),
('6219a348-d7f4-5d2b-acdc-4a5ffbb3cdb1'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Plasma volume accounts for what percentage of body weight?', '["5%","10%","20%","15%","25%"]'::jsonb, '5%', 'Plasma is approximately 5% of body weight (about 3.5 L in a 70 kg person).'),
('497a04f0-5f74-5fb0-a66f-239230d01b0c'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The principal cation in extracellular fluid is:', '["Magnesium","Potassium","Sodium","Hydrogen","Calcium"]'::jsonb, 'Sodium', 'Sodium (Na+) is the major cation in ECF, with normal concentration ~135-145 mEq/L.'),
('9c348921-cc39-560b-8d2b-74ed74c9b95d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The principal cation in intracellular fluid is:', '["Sodium","Potassium","Iron","Calcium","Magnesium"]'::jsonb, 'Potassium', 'Potassium (K+) is the major cation in ICF, with concentration ~140 mEq/L.'),
('6fd252a8-7d3a-5846-8479-4cca505ba016'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The principal anion in extracellular fluid is:', '["Chloride","Bicarbonate","Sulfate","Protein","Phosphate"]'::jsonb, 'Chloride', 'Chloride (Cl-) is the major anion in ECF, concentration ~100-110 mEq/L.'),
('b2e6d546-5b2f-5ac7-8787-fae44e2b8c67'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The principal anion in intracellular fluid is:', '["Lactate","Phosphate","Bicarbonate","Sulfate","Chloride"]'::jsonb, 'Phosphate', 'Phosphate and proteins are the major anions in ICF.'),
('8eb1adcb-aae7-5ef1-896e-550fa3dbeb9f'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'A 70 kg man has approximate total body water of:', '["70 L","42 L","50 L","60 L","30 L"]'::jsonb, '42 L', '60% of 70 kg = 42 L.'),
('ed2debfb-94b4-55e7-9299-7a685a426134'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In a 70 kg man, ICF volume is approximately:', '["14 L","35 L","42 L","50 L","28 L"]'::jsonb, '28 L', 'ICF is 40% of body weight: 0.4 x 70 = 28 L.'),
('2ee00830-d4a9-58a7-9e9c-edff049600de'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In a 70 kg man, ECF volume is approximately:', '["28 L","7 L","21 L","14 L","35 L"]'::jsonb, '14 L', 'ECF is 20% of body weight: 0.2 x 70 = 14 L.'),
('98442438-9272-56f3-9707-fb6fb52fcc6d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In a 70 kg man, plasma volume is approximately:', '["1.5 L","5.5 L","4.5 L","3.5 L","2.5 L"]'::jsonb, '3.5 L', 'Plasma is 5% of body weight: 0.05 x 70 = 3.5 L.'),
('eb3640d6-ee6a-5916-800a-8c270e4e0c99'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In a 70 kg man, interstitial fluid volume is approximately:', '["3.5 L","7 L","10.5 L","17.5 L","14 L"]'::jsonb, '10.5 L', 'Interstitial fluid = ECF - plasma = 14 - 3.5 = 10.5 L.'),
('300601ae-0869-5e3b-9588-c1d31f93957f'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Transcellular fluid volume is approximately:', '["0.5-1 L","3-4 L","7-8 L","2-3 L","5-6 L"]'::jsonb, '0.5-1 L', 'Transcellular fluid (CSF, synovial, peritoneal, pleural) is about 0.5-1 L.'),
('e36d78e5-945a-5017-a2d0-3ef27140cd07'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The method of choice for measuring total body water is:', '["Inulin","Radioactive sodium","Mannitol","Deuterium oxide","Evans blue dye"]'::jsonb, 'Deuterium oxide', 'D2O distributes throughout total body water and is used for TBW measurement.'),
('b4da7149-2351-5ff6-b450-3c3557998f74'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'ECF volume is measured using:', '["Creatinine","Radioactive iodine","D2O","Inulin or mannitol","Evans blue"]'::jsonb, 'Inulin or mannitol', 'Inulin and mannitol distribute in ECF but do not enter cells.'),
('2aca8a7f-b65b-50a3-8417-33d5a6a8157a'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Plasma volume is measured using:', '["Evans blue dye","Mannitol","Inulin","D2O","Creatinine"]'::jsonb, 'Evans blue dye', 'Evans blue binds to albumin and remains in plasma, used for plasma volume measurement.'),
('e455e4ae-71d6-5cdb-b758-dd86b7785c7b'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Blood volume can be calculated from:', '["ICF volume","Plasma volume and hematocrit","TBW","Transcellular volume","ECF volume"]'::jsonb, 'Plasma volume and hematocrit', 'Blood volume = Plasma volume / (1 - hematocrit).'),
('2dd1a6a6-3cfb-56b0-a6bf-2fc6a3892dc9'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Hematocrit in peripheral blood is normally about:', '["45%","25%","55%","65%","35%"]'::jsonb, '45%', 'Normal hematocrit is ~45% in males, ~40% in females.'),
('ec64c744-f2d2-5399-8339-7fa03e18281c'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The Gibbs-Donnan effect across capillaries results in:', '["Higher total cation concentration in plasma","Higher total anion concentration in plasma","Higher protein concentration in interstitial fluid","Equal pH","Equal cation distribution"]'::jsonb, 'Higher total cation concentration in plasma', 'Non-diffusible plasma proteins force slightly more cations into plasma to maintain electroneutrality.'),
('89d15223-26b0-55b7-a8ca-636f5d1d2fb5'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Starling forces governing fluid movement across capillaries include all EXCEPT:', '["Interstitial colloid osmotic pressure","Plasma colloid osmotic pressure","Blood pH physiological pathway","Capillary hydrostatic pressure","Interstitial hydrostatic pressure"]'::jsonb, 'Blood pH physiological pathway', 'Starling forces are hydrostatic and oncotic pressures; pH is not involved.'),
('b9d2a052-c822-53cc-9dac-fe48c9ab3985'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The primary force favoring filtration across capillaries is:', '["Lymphatic pressure","Plasma colloid osmotic pressure","Capillary hydrostatic pressure","Interstitial colloid osmotic pressure","Interstitial hydrostatic pressure"]'::jsonb, 'Capillary hydrostatic pressure', 'Capillary hydrostatic pressure (~25-35 mmHg at arterial end) drives filtration.'),
('7d830327-b46c-5b94-ab8d-93ec328d3ce6'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The primary force opposing filtration across capillaries is:', '["Lymphatic pressure","Interstitial colloid osmotic pressure","Capillary hydrostatic pressure","Interstitial hydrostatic pressure","Plasma colloid osmotic pressure"]'::jsonb, 'Plasma colloid osmotic pressure', 'Plasma colloid osmotic pressure (~25 mmHg) draws fluid back into capillaries.'),
('f29e186a-22aa-5bec-ba46-aa8749c1ce67'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Edema can result from all EXCEPT:', '["Increased capillary permeability","Decreased plasma proteins","Lymphatic obstruction","Increased capillary hydrostatic pressure","Decreased venous pressure"]'::jsonb, 'Decreased venous pressure', 'Decreased venous pressure would reduce edema, not cause it.'),
('89b064bf-b56a-5bb2-bd4e-f9d54e980de4'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which is NOT a cause of edema?', '["Cirrhosis","Nephrotic syndrome","Lymphatic obstruction","Dehydration","Heart failure"]'::jsonb, 'Dehydration', 'Dehydration causes fluid loss, not edema.'),
('fb7f6165-21c9-505b-a0af-fdf6f772cf59'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The most abundant solute in ECF is:', '["Glucose","Potassium","Bicarbonate","Urea","Sodium"]'::jsonb, 'Sodium', 'Sodium is the most abundant osmotically active solute in ECF.'),
('a496bea3-58e3-5a50-9cc2-b48230feab61'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Osmolality of body fluids is normally maintained at:', '["330-350 mOsm/L","200-220 mOsm/L","310-320 mOsm/L","250 mOsm/L","285-295 mOsm/L"]'::jsonb, '285-295 mOsm/L', 'Normal plasma osmolality is 285-295 mOsm/L.'),
('9dcd3d2d-b65e-5b53-b5b3-ce90562b95d1'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The major determinant of ECF osmolality is:', '["Potassium concentration","Glucose","Urea","Chloride concentration","Sodium concentration"]'::jsonb, 'Sodium concentration', 'Sodium and its accompanying anions account for >90% of ECF osmolality.'),
('8420e6f7-a7c0-597f-b19c-e4acfc708666'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'If plasma osmolality rises above normal, ADH secretion will:', '["Stop completely","Be unpredictable","Decrease","Stay the same","Increase"]'::jsonb, 'Increase', 'Increased osmolality stimulates osmoreceptors, increasing ADH secretion to promote water retention.'),
('73605de5-6af0-5bca-8504-fc078deb80bb'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Thirst is primarily stimulated by:', '["Increased blood volume","Decreased plasma osmolality","Decreased blood pressure","Increased plasma osmolality","Decreased ADH"]'::jsonb, 'Increased plasma osmolality', 'Osmoreceptors in hypothalamus stimulate thirst when osmolality rises >2-3%.'),
('eb371e6e-3e76-5c79-8a3a-49d6b2e7febe'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which hormone is most important for long-term regulation of ECF volume?', '["Thyroxine","Parathyroid hormone","ADH","ANP","Aldosterone"]'::jsonb, 'Aldosterone', 'Aldosterone regulates sodium and water reabsorption, controlling ECF volume long-term.'),
('14780407-4b94-5c59-a014-b0eba9ec26e8'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'ANP (atrial natriuretic peptide) is secreted in response to:', '["Decreased blood volume","Atrial stretch","Decreased blood pressure","High potassium","Low sodium"]'::jsonb, 'Atrial stretch', 'ANP is released by atrial myocytes when stretched by increased blood volume.'),
('4597dc65-ce5a-52ac-bf8a-46c687fd6f94'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'ANP causes:', '["Increased aldosterone","Vasodilation and sodium excretion","Increased ADH release","Vasoconstriction and sodium retention","Decreased GFR"]'::jsonb, 'Vasodilation and sodium excretion', 'ANP promotes natriuresis (Na excretion) and vasodilation.'),
('83b0b1ac-7e24-56cc-913f-289819d342f0'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which is a primary effect of aldosterone on the kidney?', '["Increased potassium reabsorption","Increased sodium reabsorption","Decreased sodium reabsorption","Decreased water reabsorption","Increased calcium excretion"]'::jsonb, 'Increased sodium reabsorption', 'Aldosterone stimulates Na+ reabsorption and K+ secretion in collecting duct.'),
('328cc16d-e482-568b-8bc4-cdc2976fd6df'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The renin-angiotensin-aldosterone system is activated by all EXCEPT:', '["Decreased renal perfusion","Decreased blood pressure","High sodium intake","Beta-adrenergic stimulation","Low sodium intake"]'::jsonb, 'High sodium intake', 'High sodium suppresses renin release; low sodium stimulates it.'),
('72ab8427-f692-5ec4-8588-e2f210467cfb'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Renin is secreted by:', '["Mesangial cells","Juxtaglomerular cells","Podocytes","Proximal tubule cells","Macula densa"]'::jsonb, 'Juxtaglomerular cells', 'JG cells in afferent arteriole secrete renin in response to low BP, low Na, or sympathetic stimulation.'),
('20b85299-8977-57ba-befd-f83bb9c8be4d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The macula densa senses:', '["Potassium concentration mediated physiological mechanism","Sodium chloride concentration in tubular fluid","Calcium concentration mediated physiological mechanism","Blood pressure mediated physiological mechanism","Blood osmolality mediated physiological mechanism"]'::jsonb, 'Sodium chloride concentration in tubular fluid', 'Macula densa cells in the distal tubule detect NaCl delivery and signal JG cells.'),
('0e5db9dd-4a1c-5ea1-8f69-69dc7f624879'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'For a patient presenting with symptoms, Angiotensin II causes all EXCEPT:', '["Vasodilation of renal arterioles","Aldosterone release","Increased thirst","Vasoconstriction","Increased ADH release"]'::jsonb, 'Vasodilation of renal arterioles', 'Angiotensin II is a potent vasoconstrictor, not vasodilator.'),
('1d056835-d631-5123-8a02-141b562c2903'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Angiotensin converting enzyme (ACE) is located primarily in:', '["Heart","Kidney","Liver","Lung","Brain"]'::jsonb, 'Lung', 'ACE is concentrated in pulmonary vascular endothelium.'),
('3342d27d-a5c8-51a0-988b-1faa8ba20418'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The normal plasma sodium concentration is approximately:', '["170-180 mEq/L","150-160 mEq/L","120-130 mEq/L","100-110 mEq/L","135-145 mEq/L"]'::jsonb, '135-145 mEq/L', 'Normal plasma Na+ is 135-145 mEq/L.'),
('63591389-bc00-5782-bc35-de6a22dfeecc'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Normal plasma potassium concentration is:', '["8.5-10 mEq/L","1.5-2.5 mEq/L","3.5-5.0 mEq/L","7.0-8.0 mEq/L","5.5-6.5 mEq/L"]'::jsonb, '3.5-5.0 mEq/L', 'Normal plasma K+ is 3.5-5.0 mEq/L.'),
('6a0a3672-f698-5929-9e2d-b232a82998fb'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Hyponatremia is defined as plasma Na+ less than:', '["125 mEq/L","130 mEq/L","145 mEq/L","135 mEq/L","140 mEq/L"]'::jsonb, '135 mEq/L', 'Hyponatremia is Na+ <135 mEq/L.'),
('5aa97c69-df27-5c64-ba58-097b456e6619'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Hypernatremia is defined as plasma Na+ greater than:', '["135 mEq/L","155 mEq/L","145 mEq/L","150 mEq/L","140 mEq/L"]'::jsonb, '145 mEq/L', 'Hypernatremia is Na+ >145 mEq/L.'),
('67bb297e-8337-529a-ac34-0f594d60455d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Hypokalemia is defined as plasma K+ less than:', '["4.5 mEq/L","3.5 mEq/L","2.5 mEq/L","5.0 mEq/L","3.0 mEq/L"]'::jsonb, '3.5 mEq/L', 'Hypokalemia is K+ <3.5 mEq/L.'),
('d41a17b2-9ab9-5f4e-a0b7-e4e5ea7c7312'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Hyperkalemia is defined as plasma K+ greater than:', '["5.0 mEq/L","4.0 mEq/L","4.5 mEq/L","6.0 mEq/L","5.5 mEq/L"]'::jsonb, '5.0 mEq/L', 'Hyperkalemia is K+ >5.0 mEq/L.'),
('298c96e2-b277-5062-8958-768f7c76a05e'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The sodium-potassium ATPase pump transports:', '["2 Na+ in, 3 K+ out","3 Na+ in, 2 K+ out","1 Na+ out, 1 K+ in","3 Na+ out, 2 K+ in","2 Na+ out, 3 K+ in"]'::jsonb, '3 Na+ out, 2 K+ in', 'The Na+/K+ ATPase pumps 3 Na+ out and 2 K+ in per ATP molecule.'),
('faf23784-a6a1-57bf-b370-468d5e1fbdb1'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Obligatory urine volume to excrete normal daily solute load is approximately:', '["400-500 mL","1500 mL","800-1000 mL","200 mL","100 mL"]'::jsonb, '400-500 mL', 'With max urine concentration of 1200 mOsm/L and solute load ~600 mOsm, minimum volume is ~500 mL.'),
('b216037c-8ec5-5cb0-bbb6-483cb10a54c4'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Daily water loss through insensible loss (skin and lungs) is approximately:', '["1000 mL","700 mL","100 mL","350 mL","1500 mL"]'::jsonb, '700 mL', 'Insensible loss is ~700 mL/day (skin ~350 mL, lungs ~350 mL).'),
('96214f6b-cda3-5b87-91fd-90b99c3120e6'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The minimum daily urine output to eliminate waste products is:', '["250 mL","750 mL","1000 mL","100 mL","500 mL"]'::jsonb, '500 mL', 'At least 500 mL/day is needed to excrete solutes at maximum urine concentration.'),
('85d8f9c8-a213-5804-bf8f-af78e0666c03'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which compartment expands first in overhydration?', '["ECF","Plasma","ICF","Interstitial fluid","Transcellular fluid"]'::jsonb, 'ECF', 'Excess water first distributes in ECF before moving into ICF.'),
('c5edc939-a101-5edf-af89-f1cdf57e9838'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In pure water deprivation, which compartment is primarily affected?', '["Both ECF and ICF equally","ICF only","Interstitial fluid only","ECF only","Plasma only"]'::jsonb, 'Both ECF and ICF equally', 'Water loss occurs from all compartments as osmolality rises uniformly.'),
('8767f3c5-7cd1-5867-bc5d-716ca5ccbf62'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Daily water intake from all sources in a normal adult is approximately:', '["500 mL","2500-3000 mL","3500 mL","1500-2000 mL","1000 mL"]'::jsonb, '1500-2000 mL', 'Normal daily intake: ~1500 mL from drinks, ~750 mL from food, ~300 mL metabolic water.'),
('1ba66227-5805-5046-b13e-ff9e706104f5'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Metabolic water production per day is approximately:', '["150 mL","50 mL","750 mL","300 mL","500 mL"]'::jsonb, '300 mL', 'Metabolic water from oxidation of food yields about 300 mL/day.'),
('7b035379-265e-5e1e-a517-7b3d0f47753b'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The largest daily water loss occurs through:', '["Insensible lung loss","Sweat","Feces","Insensible skin loss","Urine"]'::jsonb, 'Urine', 'Urine accounts for ~800-1500 mL/day, the largest route of water loss.'),
('3e5f2387-d08f-535d-9456-54bdab992614'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Daily fecal water loss is approximately:', '["100-200 mL","300-400 mL","50 mL","700-800 mL","500-600 mL"]'::jsonb, '100-200 mL', 'Feces contain about 100-200 mL water per day under normal conditions.'),
('fb012b02-b8aa-56dc-bbb7-489cdaa77a64'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Daily sweat water loss (at normal temperature) is approximately:', '["800-1000 mL","100 mL","500-700 mL","50 mL","200-400 mL"]'::jsonb, '200-400 mL', 'Insensible sweat and minimal active sweat is about 200-400 mL/day at normal temperature.'),
('0bff591f-52a2-50f3-b2fa-438e71636d7e'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The major route of sodium loss from the body is:', '["Feces","Lungs","Sweat","Urine","Skin"]'::jsonb, 'Urine', 'The kidney regulates sodium excretion; urinary Na+ loss is the primary route.'),
('8b9569ab-481c-5fe1-8004-4ec650aaafad'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Daily sodium intake in a typical Western diet is approximately:', '["20-25 g","500-1000 mg","2-6 g","50-100 mg","10-15 g"]'::jsonb, '2-6 g', 'Typical Na+ intake is 2-6 g/day (equivalent to 5-15 g salt).'),
('d37a1960-764c-58a2-a08c-9c63be9b56cd'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The kidney can reduce sodium excretion to as low as:', '["1-5 mEq/day","50-75 mEq/day","10-20 mEq/day","30-40 mEq/day","0 mEq/day"]'::jsonb, '1-5 mEq/day', 'On low Na+ diet, kidneys can conserve Na+, excreting as little as 1-5 mEq/day.'),
('5a64fcdd-9698-5721-906a-7c8e874746a0'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which of the following is a potent stimulus for aldosterone secretion?', '["Low plasma K+","High blood volume","Low plasma Na+","High plasma Na+","High plasma K+"]'::jsonb, 'High plasma K+', 'Hyperkalemia is a direct and potent stimulus for aldosterone release.'),
('dffc0a7e-43d3-51df-a9f9-94af42b42a8f'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Aldosterone synthesis is stimulated by all EXCEPT:', '["High plasma Na+","High plasma K+","Angiotensin II","Low plasma Na+","ACTH"]'::jsonb, 'High plasma Na+', 'High Na+ suppresses the RAAS and aldosterone; low Na+ stimulates it.'),
('c5459374-700f-5c93-9a2b-98fe9dd0ea6f'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which diuretic acts by inhibiting the Na+-K+-2Cl- cotransporter in the thick ascending limb?', '["Spironolactone","Hydrochlorothiazide","Furosemide","Amiloride","Acetazolamide"]'::jsonb, 'Furosemide', 'Furosemide is a loop diuretic that inhibits NKCC2 in the thick ascending limb.'),
('fbff1e32-909f-5fa9-8a81-7e97ebfb7efe'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which diuretic acts on the distal convoluted tubule inhibiting Na+-Cl- cotransport?', '["Spironolactone","Acetazolamide","Hydrochlorothiazide","Furosemide","Mannitol"]'::jsonb, 'Hydrochlorothiazide', 'Thiazide diuretics inhibit NCC in the DCT.'),
('8d827692-6095-54cd-983a-61131d2b386c'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which diuretic is a carbonic anhydrase inhibitor?', '["Hydrochlorothiazide","Spironolactone","Acetazolamide","Furosemide","Amiloride"]'::jsonb, 'Acetazolamide', 'Acetazolamide inhibits carbonic anhydrase in proximal tubule.'),
('6a871322-d6aa-56fb-b8ce-caf06584fbf0'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which diuretic acts as an aldosterone antagonist?', '["Furosemide","Mannitol","Hydrochlorothiazide","Spironolactone","Acetazolamide"]'::jsonb, 'Spironolactone', 'Spironolactone competitively inhibits aldosterone receptors in collecting duct.'),
('f81cfab6-71f5-519f-812a-2521913ef5dc'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which diuretic blocks ENaC (epithelial sodium channels) in the collecting duct?', '["Furosemide","Hydrochlorothiazide","Spironolactone","Amiloride","Acetazolamide"]'::jsonb, 'Amiloride', 'Amiloride blocks ENaC directly, causing K+-sparing diuresis.'),
('3bb555f2-c6fc-5a44-87dd-4e896652bd86'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Mannitol is classified as which type of diuretic?', '["K+-sparing","Carbonic anhydrase inhibitor","Osmotic diuretic","Loop diuretic","Thiazide"]'::jsonb, 'Osmotic diuretic', 'Mannitol is an osmotic diuretic that is filtered but not reabsorbed.'),
('69d8ffbc-acc6-5cfa-a112-d0c7eac8f782'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The most common cause of hyponatremia in hospitalized patients is:', '["SIADH","Adrenal insufficiency","Primary polydipsia","Hypothyroidism","Diuretic use"]'::jsonb, 'SIADH', 'SIADH (syndrome of inappropriate ADH secretion) is the most common cause.'),
('9014688a-8251-5324-bf32-c902042d8baf'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The treatment of choice for severe symptomatic hyponatremia is:', '["Hypertonic (3%) saline","Vasopressin antagonists","Salt tablets","Water restriction","Normal saline"]'::jsonb, 'Hypertonic (3%) saline', '3% saline is used cautiously in severe symptomatic hyponatremia to raise Na+.'),
('04e52b07-891d-55a9-b4e7-d598c19c37ee'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Central diabetes insipidus results from deficiency of:', '["Angiotensin II","ANP","Renin","ADH","Aldosterone"]'::jsonb, 'ADH', 'Central DI is due to deficient ADH secretion from posterior pituitary.'),
('e8b7e479-cf96-535e-84fb-6671896827eb'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Nephrogenic diabetes insipidus results from:', '["ADH resistance in kidneys","Aldosterone excess","Renin excess","Excessive ADH","ADH deficiency"]'::jsonb, 'ADH resistance in kidneys', 'Nephrogenic DI is due to renal resistance to ADH.'),
('2806698f-fcb5-52cf-8f29-cbacc84dbec6'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'A patient with diabetes insipidus will have:', '["High urine output, high urine osmolality","Low urine output, low urine osmolality","Low urine output, high urine osmolality","High urine output, low urine osmolality","Normal urine output"]'::jsonb, 'High urine output, low urine osmolality', 'DI produces large volumes of dilute urine (low osmolality).'),
('3a86c7a7-513e-5fff-a79d-ae05c6f0234c'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Daily obligatory urine volume in a patient with diabetes insipidus is:', '["1000 mL","5-10 L or more","2-3 L","500 mL","15-20 L"]'::jsonb, '5-10 L or more', 'Patients with DI excrete large volumes, often >5 L/day.'),
('dc6b38ee-f061-5c2d-bec2-fa7cba625642'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The most important buffer in the ECF is:', '["Bicarbonate buffer","Phosphate buffer","Protein buffer","Hemoglobin buffer","Ammonia buffer"]'::jsonb, 'Bicarbonate buffer', 'The bicarbonate/carbonic acid system is the primary ECF buffer.'),
('c64b9dd0-700f-5e91-ae7d-50090cd594f0'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Normal anion gap is approximately:', '["25-30 mEq/L","19-24 mEq/L","13-18 mEq/L","8-12 mEq/L","5-7 mEq/L"]'::jsonb, '8-12 mEq/L', 'Normal anion gap (Na - [Cl + HCO3]) is 8-12 mEq/L.'),
('62688fdb-6f24-578d-b75f-773e5cd7cdbf'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'An unmeasured anion that contributes to the anion gap is:', '["Chloride","Bicarbonate","Albumin","Sodium","Potassium"]'::jsonb, 'Albumin', 'Albumin is a negatively charged protein that contributes to the anion gap.'),
('ff163d30-a686-5275-9f43-d2dfa675cda7'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The most common cause of hyperkalemia is:', '["Vomiting","Primary aldosteronism","Renal failure","SIADH","Diuretic use"]'::jsonb, 'Renal failure', 'Renal failure impairs K+ excretion, leading to hyperkalemia.'),
('6f2429f1-1981-58ba-8db2-317cfb794b4c'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The most common cause of hypokalemia is:', '["Adrenal insufficiency","Renal failure","Excessive intake","Metabolic acidosis","Diuretic therapy"]'::jsonb, 'Diuretic therapy', 'Loop and thiazide diuretics increase K+ loss, causing hypokalemia.'),
('3c893abb-5efc-5b4c-9d2a-d219b2690988'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Total body sodium is primarily regulated by:', '["PTH","Aldosterone","ADH","ANP","Thyroxine"]'::jsonb, 'Aldosterone', 'Aldosterone controls Na+ reabsorption, regulating total body sodium.'),
('1cbd2127-a124-5171-b00b-1626b120fce2'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Total body water is primarily regulated by:', '["Renin","Aldosterone","Angiotensin II","ANP","ADH"]'::jsonb, 'ADH', 'ADH controls water reabsorption, regulating total body water.'),
('f467101f-9ae4-5f08-9d30-5c014d04326e'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Vasopressin (ADH) acts on which part of the nephron?', '["Proximal tubule","Thick ascending limb","Distal convoluted tubule","Collecting duct","Thin descending limb"]'::jsonb, 'Collecting duct', 'ADH acts on V2 receptors in the collecting duct to insert aquaporin-2 channels.'),
('7ba14bf0-3e3d-55c6-bc62-8267bb6361af'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The primary intracellular buffer is:', '["Hemoglobin","Protein","Bicarbonate","Ammonia","Phosphate"]'::jsonb, 'Protein', 'Proteins are the most abundant and important intracellular buffers.'),
('2be21663-6d30-590d-a6c5-9ff0ef0c58f3'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The normal glomerular filtration rate (GFR) is approximately:', '["50 mL/min","125 mL/min","100 mL/min","150 mL/min","200 mL/min"]'::jsonb, '125 mL/min', 'Normal GFR is about 125 mL/min or 180 L/day.'),
('e0ebaa53-b78e-5b2b-8d34-8eeeb7f24849'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Daily filtration volume is approximately:', '["250 L","180 L","100 L","300 L","50 L"]'::jsonb, '180 L', '180 L/day = 125 mL/min x 1440 min.'),
('9ee0d255-9e67-5696-974f-86eaeeb2984d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The substance used as the gold standard for measuring GFR is:', '["Urea","Inulin","Mannitol","PAH","Creatinine"]'::jsonb, 'Inulin', 'Inulin is freely filtered, not reabsorbed or secreted, making it ideal for GFR measurement.'),
('b2b3f8c3-909e-5278-b048-8e5d5802c785'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In clinical practice, GFR is most commonly estimated using:', '["Creatinine clearance","PAH clearance","Urea clearance","D2O clearance","Inulin clearance"]'::jsonb, 'Creatinine clearance', 'Creatinine clearance is routinely used as a practical estimate of GFR.'),
('e7288665-7aa6-571c-9e1e-622f532bb902'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The normal renal plasma flow (RPF) is approximately:', '["450 mL/min","800 mL/min","300 mL/min","625 mL/min","1000 mL/min"]'::jsonb, '625 mL/min', 'Normal RPF is ~625 mL/min (renal blood flow ~1200 mL/min x [1-Hct]).'),
('6b76a73e-8f96-57a5-a22e-a36f2def03ea'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'PAH clearance is used to measure:', '["Tubular reabsorption","Concentrating ability","Tubular secretion","Renal plasma flow","GFR"]'::jsonb, 'Renal plasma flow', 'PAH is completely extracted in one pass, so its clearance equals RPF.'),
('4fe8b237-771f-56f2-bdd9-08d992f593ff'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Filtration fraction (FF) is normally about:', '["15%","20%","10%","30%","25%"]'::jsonb, '20%', 'FF = GFR/RPF = 125/625 = 0.2 or 20%.'),
('a5dc2169-4c48-5d5e-893b-f4a73fcfd0c2'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Net filtration pressure in glomerular capillaries is approximately:', '["5 mmHg","10 mmHg","20 mmHg","25 mmHg","15 mmHg"]'::jsonb, '10 mmHg', 'Net filtration pressure = Pgc - Pbc - pi_gc ~ 60 - 15 - 25 = 10 mmHg.'),
('ee0dae7d-c8bf-54f9-9ca1-6c4658cbf598'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which of the following increases GFR?', '["Decreased renal blood flow","Increased plasma colloid osmotic pressure","Efferent arteriolar constriction","Afferent arteriolar constriction","Decreased glomerular capillary pressure"]'::jsonb, 'Efferent arteriolar constriction', 'Efferent arteriolar constriction increases glomerular capillary pressure, raising GFR.'),
('df84bb39-dedb-541a-87e8-dd5a8eaf6ecd'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Afferent arteriolar constriction causes:', '["Increased filtration fraction","No change in GFR","Increased GFR","Decreased GFR","Increased RPF"]'::jsonb, 'Decreased GFR', 'Afferent constriction reduces blood flow and pressure into glomerulus, decreasing GFR.'),
('7efc4735-a6db-559f-8da2-7f85f88ac87d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Autoregulation of GFR is mediated by:', '["Tubuloglomerular feedback and myogenic response","Hormonal mechanisms mediated physiological mechanism","pH changes mediated physiological mechanism","Temperature changes mediated physiological mechanism","Neural mechanisms mediated physiological mechanism"]'::jsonb, 'Tubuloglomerular feedback and myogenic response', 'Autoregulation maintains GFR constant across BP 80-180 mmHg via myogenic and TGF mechanisms.'),
('774cfab4-1f92-547d-a813-5e7e1adaa26e'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The myogenic response in renal autoregulation refers to:', '["Changes in mesangial cell contraction","Constriction of efferent arteriole when BP increases","Constriction of afferent arteriole when BP increases","Dilation of afferent arteriole when BP increases","Dilation of efferent arteriole when BP decreases"]'::jsonb, 'Constriction of afferent arteriole when BP increases', 'Smooth muscle in afferent arteriole contracts in response to stretch from increased pressure.'),
('b716ce55-ccdd-5d10-b35e-b6ec347e3e27'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Tubuloglomerular feedback involves the:', '["Proximal tubule","Collecting duct","Distal tubule only","Loop of Henle","Juxtaglomerular apparatus"]'::jsonb, 'Juxtaglomerular apparatus', 'The JGA mediates TGF where macula densa senses NaCl and signals afferent arteriole.'),
('0ede64a2-7516-50ae-9d99-52a455837915'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'An increase in NaCl delivery to the macula densa leads to:', '["Increased GFR","Efferent arteriolar dilation","Afferent arteriolar constriction","Increased renin release","Afferent arteriolar dilation"]'::jsonb, 'Afferent arteriolar constriction', 'High NaCl at macula densa signals afferent constriction via adenosine, reducing GFR (TGF).'),
('48b564a4-9699-528a-a9d6-49f8fbb0066d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'What does U represent?', '["Volume of urine","Urine flow rate","Concentration of substance in urine","Plasma volume","Concentration of substance in plasma"]'::jsonb, 'Concentration of substance in urine', 'U is urine concentration of the substance.'),
('feba5a16-1d00-55e3-98a2-7f0d994691d8'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'A substance freely filtered and completely secreted would have a clearance:', '["Equal to RPF","Equal to zero","Greater than GFR","Less than GFR","Equal to GFR"]'::jsonb, 'Greater than GFR', 'Complete secretion adds more substance to urine, making clearance > GFR.'),
('7d722d3e-d2bc-50c6-808c-8aefa8a6001a'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'A substance that is filtered and completely reabsorbed would have a clearance of:', '["Less than GFR","Greater than GFR","Equal to RPF","Zero physiological pathway","Equal to GFR"]'::jsonb, 'Zero physiological pathway', 'Complete reabsorption means none appears in urine, so clearance = 0.'),
('1e4d843c-8e1a-56bf-ad4a-963e8e99ec0a'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Creatinine clearance overestimates GFR because:', '["Creatinine is not filtered","Creatinine is secreted by tubules","Creatinine is protein-bound","Creatinine is reabsorbed","Creatinine is metabolized"]'::jsonb, 'Creatinine is secreted by tubules', 'A small amount of creatinine is secreted, causing clearance to slightly overestimate GFR.'),
('b2dff0ff-90ea-54b3-8b5c-dd3be1a15c12'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The normal serum creatinine level is:', '["0.1-0.3 mg/dL","2.5-4.0 mg/dL","4.0-6.0 mg/dL","1.5-2.5 mg/dL","0.5-1.2 mg/dL"]'::jsonb, '0.5-1.2 mg/dL', 'Normal serum creatinine is 0.5-1.2 mg/dL depending on muscle mass.'),
('36469644-ca94-576e-be54-d4a6fe9c0c3d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Blood urea nitrogen (BUN) normally ranges from:', '["25-40 mg/dL","7-20 mg/dL","2-5 mg/dL","65-80 mg/dL","45-60 mg/dL"]'::jsonb, '7-20 mg/dL', 'Normal BUN is 7-20 mg/dL.'),
('76e9a5f7-1214-53a4-a710-ecc196428094'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The BUN-to-creatinine ratio is normally about:', '["5:1","15:1","20:1","25:1","10:1"]'::jsonb, '10:1', 'Normal BUN:Cr ratio is ~10:1.'),
('75cd0090-0b55-5cfd-8842-aba9adde317f'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'A BUN-to-creatinine ratio >20:1 suggests:', '["Pre-renal azotemia","Liver disease","Malnutrition","Post-renal obstruction","Renal parenchymal disease"]'::jsonb, 'Pre-renal azotemia', 'Elevated BUN:Cr ratio suggests decreased renal perfusion (pre-renal).'),
('b485696f-5c11-5894-8a8c-77c09b5b8911'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Renal clearance of a substance is defined as:', '["The volume of plasma from which the substance is completely removed per minute","The rate of tubular secretion mediated physiological mechanism","The volume of urine produced per minute mediated physiological mechanism","The rate of glomerular filtration mediated physiological mechanism","The amount of substance excreted per minute mediated physiological mechanism"]'::jsonb, 'The volume of plasma from which the substance is completely removed per minute', 'Clearance is the virtual volume of plasma cleared of the substance per unit time.'),
('2d4a827e-79bb-514e-8b96-cb843391d973'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Inulin clearance is approximately:', '["200 mL/min","150 mL/min","175 mL/min","125 mL/min","100 mL/min"]'::jsonb, '125 mL/min', 'Inulin clearance equals GFR ~125 mL/min.'),
('f0ec6e46-b165-588d-a07d-5c38aba9348b'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Glucose clearance in a normal individual is:', '["About 0 mL/min","625 mL/min","125 mL/min","50 mL/min","200 mL/min"]'::jsonb, 'About 0 mL/min', 'Glucose is completely reabsorbed in proximal tubule, so clearance is nearly zero.'),
('79c96b42-964d-5771-b91e-d2c0e8d7895b'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Renal threshold for glucose is approximately:', '["250 mg/dL","180 mg/dL","100 mg/dL","400 mg/dL","300 mg/dL"]'::jsonb, '180 mg/dL', 'When plasma glucose exceeds ~180 mg/dL, transport maximum is exceeded and glucosuria occurs.'),
('f2a01d91-2094-5f1d-922a-0c4844152917'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The transport maximum (Tm) for glucose is approximately:', '["250 mg/min","320 mg/min","425 mg/min","375 mg/min","175 mg/min"]'::jsonb, '375 mg/min', 'Tm for glucose is about 375 mg/min.'),
('a83b0cc6-b8c0-5684-95af-25b84b6e2323'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which of the following decreases GFR?', '["Renal artery stenosis","High","Pregnancy","Efferent arteriolar constriction","Decreased plasma protein"]'::jsonb, 'Renal artery stenosis', 'Renal artery stenosis reduces perfusion pressure, decreasing GFR.'),
('92517b2a-cce2-515a-84ec-4318bb9c062a'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Pregnancy typically causes GFR to:', '["Increase by 50%","Decrease by 50%","Increase by 10%","Remain unchanged","Decrease by 25%"]'::jsonb, 'Increase by 50%', 'GFR increases ~50% during pregnancy due to increased renal blood flow.'),
('6ebcfcc4-24aa-539b-9f26-86fb57a0bd73'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The protein Tamm-Horsfall is secreted by:', '["Collecting duct","Thick ascending limb","Distal convoluted tubule","Proximal tubule","Glomerulus"]'::jsonb, 'Thick ascending limb', 'Tamm-Horsfall protein (uromodulin) is secreted by cells of the thick ascending limb.'),
('fb149352-f9b3-5412-a16d-917e6c747094'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The glomerular filtration barrier consists of all EXCEPT:', '["Glomerular basement membrane","Mesangial matrix","Glycocalyx layer","Fenestrated endothelium","Podocyte foot processes"]'::jsonb, 'Mesangial matrix', 'The filtration barrier is endothelium, GBM, and podocyte slit diaphragm; mesangium supports but is not part of the barrier.'),
('91210d22-e765-58aa-a9f2-a3f843b80c5f'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The size selectivity of the glomerular filtration barrier excludes molecules larger than:', '["100 kDa","150 kDa","70 kDa","30 kDa","10 kDa"]'::jsonb, '70 kDa', 'Albumin (69 kDa) is largely excluded; molecules >70 kDa are effectively prevented from filtration.'),
('c229c0cb-d3f0-59a8-bc88-92e4c74874af'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The glomerular filtration barrier has a negative charge that:', '["Repels negatively charged proteins","Has no effect on filtration","Attracts positively charged solutes","Attracts negatively charged proteins","Repels neutral molecules"]'::jsonb, 'Repels negatively charged proteins', 'Negative charge of GBM repels negatively charged proteins like albumin (charge selectivity).'),
('c325489d-1db1-5d1c-b2fb-24cddb8a8093'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Podocytes are specialized epithelial cells that:', '["Secrete renin","Contract to regulate GFR","Sense NaCl concentration","Line the proximal tubule","Form the slit diaphragm in the glomerulus"]'::jsonb, 'Form the slit diaphragm in the glomerulus', 'Podocytes have foot processes connected by slit diaphragms that form part of the filtration barrier.'),
('a4f4be7f-4b30-5d83-b6b7-ecb24aa0ec79'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Mesangial cells in the glomerulus function to:', '["Secrete ADH","Produce renin","Contract and regulate GFR","Filter blood","Reabsorb glucose"]'::jsonb, 'Contract and regulate GFR', 'Mesangial cells can contract to reduce filtration surface area, decreasing GFR.'),
('6fe974c6-f38e-5756-9144-a10481094a55'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The normal renal blood flow is approximately:', '["1500 mL/min","500 mL/min","1800 mL/min","800 mL/min","1200 mL/min"]'::jsonb, '1200 mL/min', 'Renal blood flow is ~1200 mL/min or about 20-25% of cardiac output.'),
('5ee0fb4b-bf42-5aee-bc12-851d4460c57a'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The kidneys receive what percentage of cardiac output?', '["5-10%","10-15%","40-45%","20-25%","30-35%"]'::jsonb, '20-25%', 'Despite being less than 0.5% of body weight, kidneys receive 20-25% of cardiac output.'),
('67716a3d-c93f-531b-99a0-e1b00cf1c04d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The pressure at which GFR autoregulation fails (below which GFR falls) is:', '["60 mmHg","100 mmHg","40 mmHg","80 mmHg","120 mmHg"]'::jsonb, '80 mmHg', 'Autoregulation maintains GFR down to ~80 mmHg MAP.'),
('04a1b970-89c3-5a80-b569-52b1dbea5184'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Which vasodilator can disrupt renal autoregulation?', '["Prostaglandin E2","Norepinephrine","Adenosine","Angiotensin II","Endothelin"]'::jsonb, 'Prostaglandin E2', 'PGE2 is a vasodilator that can attenuate autoregulation.'),
('0f114d2c-70b0-500a-91c3-e8e28ed665ea'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In calculating creatinine clearance, a 24-hour urine collection is used. The formula is:', '["CrCl = (P x V)/U","CrCl = (U x P)/V","CrCl = (U + V)/P","CrCl = (V x P)/U","CrCl = (U x V)/P"]'::jsonb, 'CrCl = (U x V)/P', 'Creatinine clearance = (Urine creatinine x Urine flow rate) / Plasma creatinine.'),
('4125ba67-6aed-51bb-8aea-dc217d5880a7'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The proximal tubule reabsorbs approximately what percentage of filtered sodium?', '["40%","95%","50%","65%","80%"]'::jsonb, '65%', 'About 65% of filtered Na+ is reabsorbed in the proximal tubule.'),
('9bb3bbd1-84a5-598e-98a8-d6164693e45d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The proximal tubule reabsorbs approximately what percentage of filtered water?', '["90%","50%","65%","99%","80%"]'::jsonb, '65%', 'Proximal tubule reabsorbs ~65% of filtered water isotonically.'),
('1df92fa9-89f5-589c-b178-7fa7dee6e4c9'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The proximal tubule reabsorbs approximately what percentage of filtered glucose?', '["100%","99%","65%","80%","50%"]'::jsonb, '100%', 'Under normal conditions, glucose is completely (100%) reabsorbed in the proximal tubule.'),
('f6fb1a0c-c478-5f56-aa7b-c7298118cb67'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Glucose reabsorption in the proximal tubule occurs via:', '["Facilitated diffusion","Primary active transport","Simple diffusion","Solvent drag","Secondary active transport"]'::jsonb, 'Secondary active transport', 'SGLT2 and SGLT1 are sodium-glucose cotransporters (secondary active transport).'),
('1ca452a8-35b0-50c6-9a14-cbd5fcd3e60e'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Sodium reabsorption in the proximal tubule is primarily:', '["Active transcellular via Na+/K+ ATPase","Via Na+/K+/2Cl- cotransport","Via ENaC channels","Via Na+/Cl- cotransporter","Passive paracellular"]'::jsonb, 'Active transcellular via Na+/K+ ATPase', 'Basolateral Na+/K+ ATPase creates electrochemical gradient for Na+ entry.'),
('cc8b8627-a679-5425-8ff2-405e3c48826d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Bicarbonate reabsorption in the proximal tubule is mediated by:', '["Na+/HCO3- cotransport","Simple diffusion","H+ secretion and carbonic anhydrase","Cl-/HCO3- exchange","Aquaporins"]'::jsonb, 'H+ secretion and carbonic anhydrase', 'H+ is secreted into lumen, combines with HCO3- to form H2CO3, then CO2 and H2O via carbonic anhydrase.'),
('295db1a3-f159-5853-970e-560c39eb5cf2'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'Carbonic anhydrase inhibitors cause:', '["Metabolic alkalosis","Respiratory acidosis","Respiratory alkalosis","Metabolic acidosis","No acid-base effect"]'::jsonb, 'Metabolic acidosis', 'Blocking HCO3- reabsorption causes bicarbonate loss in urine, producing metabolic acidosis.'),
('109f9374-e06e-5062-b4ee-aefa1fa8d1fb'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The phosphate threshold (TmP/GFR) is regulated mainly by:', '["Estrogen","Vitamin D","Calcitonin","FGF23","PTH"]'::jsonb, 'PTH', 'PTH increases phosphate excretion by decreasing reabsorption in proximal tubule.'),
('a600f786-28cd-5944-a593-545a396bc6b7'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The thick ascending limb reabsorbs which ions via NKCC2?', '["Na+ and Ca2+","K+ and HCO3-","Na+ and Cl- only","Na+, Ca2+ and Mg2+","Na+, K+ and Cl-"]'::jsonb, 'Na+, K+ and Cl-', 'The Na+/K+/2Cl- cotransporter (NKCC2) transports 1 Na+, 1 K+, and 2 Cl-.'),
('940d68a5-eed9-5ad4-87e2-deb0aaa2ef98'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In the thick ascending limb, K+ recycling across the apical membrane:', '["Inhibits NaCl reabsorption","Generates a positive lumen potential","Conserves K+","Reabsorbs Ca2+","Secretes H+"]'::jsonb, 'Generates a positive lumen potential', 'K+ recycling via ROMK channels creates positive transepithelial voltage driving paracellular cation reabsorption.'),
('954ba5b0-60eb-5fdc-a5eb-d1d4e9590942'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'The distal convoluted tubule reabsorbs NaCl via:', '["NCC","ENaC","NKCC2","Na+/H+ exchanger","SGLT"]'::jsonb, 'NCC', 'The thiazide-sensitive Na+/Cl- cotransporter (NCC) is in the DCT.'),
('a54ddff0-118c-5fc9-a4e4-c5f17faefa8d'::uuid, 'Physiology (Paper 2)', 'Renal and Body Fluids', 'In the collecting duct, principal cells are responsible for:', '["Bicarbonate reabsorption","Glucose reabsorption","Na+ reabsorption and K+ secretion","H+ secretion","Phosphate reabsorption"]'::jsonb, 'Na+ reabsorption and K+ secretion', 'Principal cells reabsorb Na+ via ENaC and secrete K+ via ROMK channels.'),
